import justPick from"just-pick";import{vToken}from"../action/api-middleware.js";import*as noteServer from"../service/note.js";import{PublicReturn}from"../common/public-return.js";import{noteAddValidatorFn,noteUpdateValidatorFn}from"../action/verified-option.js";import{createUuid}from"../common/uuid-tools.js";import{toBoolean}from"../common/other-tools.js";export function createRouter(e){e.get("/note/list",{preHandler:vToken},async function(e,n){const t=e.query||{},o=Math.abs(parseInt(t.page))||1,i=Math.abs(parseInt(t.size))||10,d=[];"pinned"===t.sortBy&&d.push(["pinned","DESC"]),d.push(["initDate","DESC"]);const r={};Object.prototype.hasOwnProperty.call(t,"title")&&""!==t.title&&(r.title=t.title),Object.prototype.hasOwnProperty.call(t,"hidden")&&""!==t.hidden&&(r.hidden=String(toBoolean(t.hidden))),Object.prototype.hasOwnProperty.call(t,"pinned")&&""!==t.pinned&&(r.pinned=String(toBoolean(t.pinned)));const s={},a=e.userInfo||{};"admin"!==a.userRole&&(s.userUId=a.uId,"all"!==t.scope&&(s.hidden=!1));const u=await noteServer.list({page:o,size:i,sortBy:d,searchBy:r,where:s});n.send(new PublicReturn(200,"数据列表",{list:u.list,total:u.total,page:o,size:i}))}),e.get("/note/info/:uId",{preHandler:vToken},async function(e,n){const t=e.params||{},o=await noteServer.findById(t.uId);if(!o)return void n.code(404).send(new PublicReturn(404,"获取失败: 什么也没找到"));const i=e.userInfo||{};o.hidden&&"admin"!==i.userRole&&o.userUId!==i.uId?n.code(403).send(new PublicReturn(403,"无权查看此日记")):n.send(new PublicReturn(200,"成功",o))}),e.post("/note/add",{preHandler:vToken},async function(e,n){const t=justPick(e.body||{},["title","content","hidden","pinned"]),o=noteAddValidatorFn(t);if(o)return void n.code(400).send(new PublicReturn(400,o));const i=e.userInfo||{},d=(new Date).getTime(),r={uId:createUuid(),userUId:i.uId,title:t.title||"",content:t.content,hidden:!!t.hidden,pinned:!!t.pinned,initDate:d,updateDate:d},s=await noteServer.add(r);n.send(new PublicReturn(200,"成功",s))}),e.put("/note/update",{preHandler:vToken},async function(e,n){const t=justPick(e.body||{},["uId","title","content","hidden","pinned"]),o=noteUpdateValidatorFn(t);if(o)return void n.code(400).send(new PublicReturn(400,o));const i=await noteServer.findById(t.uId);if(!i)return void n.code(404).send(new PublicReturn(404,"修改失败: 未找到相应数据"));const d=e.userInfo||{};"admin"===d.userRole||i.userUId===d.uId?(t.updateDate=(new Date).getTime(),await noteServer.update(i,t),n.send(new PublicReturn(200,"成功",t))):n.code(403).send(new PublicReturn(403,"无权修改此日记"))}),e.delete("/note/:ids",{preHandler:vToken},async function(e,n){const t=((e.params||{}).ids||"").split(",");if(0==t.length)return void n.code(400).send(new PublicReturn(400,"参数不能为空"));const o=e.userInfo||{},i=await noteServer.filter(e=>!!t.includes(e.uId)&&("admin"===o.userRole||e.userUId===o.uId));await noteServer.delete_(i),n.send(new PublicReturn(200,"成功"))})}